SELECT ROUND(
    100.0 * COUNT(DISTINCT fd.uuid) / (SELECT COUNT(*) FROM cards),
    2
) AS percentage
FROM foreign_data AS fd
WHERE fd.language = 'Chinese Simplified';

SELECT DISTINCT text
FROM cards
WHERE name = 'Benalish Knight';

SELECT id
FROM cards
WHERE duelDeck = 'a';

SELECT COUNT(DISTINCT scryfallOracleId)
FROM cards
WHERE ',' || promoTypes || ',' LIKE '%,release,%';

SELECT ROUND(
    100.0 * SUM(
        CASE WHEN EXISTS (
            SELECT 1
            FROM Player_Attributes pa
            WHERE pa.player_api_id = p.player_api_id
              AND pa.overall_rating > 70
        ) THEN 1 ELSE 0 END
    ) / COUNT(*),
    2
) AS percentage
FROM Player p
WHERE p.height < 180;

SELECT notes
FROM income
WHERE date_received = '2019-09-14';

SELECT ROUND(
    100.0 * (
        COUNT(*) - COUNT(DISTINCT m.link_to_major)
    ) / COUNT(*),
    2
) AS percentage_unrepresented
FROM major AS ma
LEFT JOIN member AS m
    ON m.link_to_major = ma.major_id;

SELECT ROUND(
    100.0 * SUM(CASE WHEN Diagnosis LIKE '%SLE%' THEN 1 ELSE 0 END) / COUNT(*),
    2
) AS percentage
FROM Examination
WHERE Thrombosis IN (1, 2, 3);

SELECT ROUND(
    100.0 * SUM(
        CASE WHEN NOT EXISTS (
            SELECT 1
            FROM atom AS a
            WHERE a.molecule_id = m.molecule_id
              AND a.element = 'f'
        ) THEN 1 ELSE 0 END
    ) / COUNT(*),
    2
) AS percentage
FROM molecule AS m
WHERE m.label = '+';
